def exchange(lst1, lst2): 
    # Check if all numbers in lst1 are even
    def check_even_numbers(lst):
        return all(num % 2 == 0 for num in lst)

    # Exchange elements between lst1 and lst2 to make lst1 have only even numbers
    while not check_even_numbers(lst1) and lst2:
        if any(num % 2 != 0 for num in lst2):
            odd_num = next((num for num in lst2 if num % 2 != 0), None)
            lst1.append(odd_num)
            lst2.remove(odd_num)

    # Determine the result based on conditions of exchanges
    return 'YES' if check_even_numbers(lst1) else 'NO'
